using System.Security.Claims;
using Microsoft.AspNetCore.Http.HttpResults;
using Microsoft.EntityFrameworkCore;
using ShipmentTracker.Client.Models;
using ShipmentTracker.Data;

namespace ShipmentTracker.Endpoints;

public static class ShipmentEndpoints
{
    public static void MapShipmentEndpoints(this WebApplication app)
    {
        var group = app.MapGroup("/api/shipments").RequireAuthorization();

        // GET all shipments (dispatchers see all, customers see only theirs)
        group.MapGet("/", async (ApplicationDbContext db, ClaimsPrincipal user) =>
        {
            var email = user.FindFirstValue(ClaimTypes.Email) ?? user.FindFirstValue(ClaimTypes.Name);
            var role = await GetUserRole(db, user);

            IQueryable<Shipment> query = db.Shipments.OrderByDescending(s => s.ShippedDate);

            if (role != "Dispatcher")
                query = query.Where(s => s.CustomerEmail == email);

            var shipments = await query.Select(s => s.ToDto()).ToListAsync();
            return Results.Ok(shipments);
        });

        // GET single shipment
        group.MapGet("/{id:int}", async (int id, ApplicationDbContext db, ClaimsPrincipal user) =>
        {
            var shipment = await db.Shipments.FindAsync(id);
            if (shipment is null) return Results.NotFound();

            var email = user.FindFirstValue(ClaimTypes.Email) ?? user.FindFirstValue(ClaimTypes.Name);
            var role = await GetUserRole(db, user);

            if (role != "Dispatcher" && shipment.CustomerEmail != email)
                return Results.Forbid();

            return Results.Ok(shipment.ToDto());
        });

        // GET shipment by tracking number (for customer lookup)
        group.MapGet("/track/{trackingNumber}", async (string trackingNumber, ApplicationDbContext db, ClaimsPrincipal user) =>
        {
            var shipment = await db.Shipments
                .FirstOrDefaultAsync(s => s.TrackingNumber == trackingNumber);

            if (shipment is null) return Results.NotFound();

            var email = user.FindFirstValue(ClaimTypes.Email) ?? user.FindFirstValue(ClaimTypes.Name);
            var role = await GetUserRole(db, user);

            if (role != "Dispatcher" && shipment.CustomerEmail != email)
                return Results.Forbid();

            return Results.Ok(shipment.ToDto());
        });

        // POST create shipment (dispatchers only)
        group.MapPost("/", async (CreateShipmentRequest request, ApplicationDbContext db, ClaimsPrincipal user) =>
        {
            var role = await GetUserRole(db, user);
            if (role != "Dispatcher") return Results.Forbid();

            var shipment = new Shipment
            {
                TrackingNumber = GenerateTrackingNumber(),
                Origin = request.Origin,
                Destination = request.Destination,
                Status = ShipmentStatus.Pending,
                ShippedDate = DateTime.UtcNow,
                EstimatedDelivery = request.EstimatedDelivery,
                RecipientName = request.RecipientName,
                CustomerEmail = request.CustomerEmail,
                Notes = request.Notes
            };

            db.Shipments.Add(shipment);
            await db.SaveChangesAsync();
            return Results.Created($"/api/shipments/{shipment.Id}", shipment.ToDto());
        });

        // PUT update shipment (dispatchers only)
        group.MapPut("/{id:int}", async (int id, UpdateShipmentRequest request, ApplicationDbContext db, ClaimsPrincipal user) =>
        {
            var role = await GetUserRole(db, user);
            if (role != "Dispatcher") return Results.Forbid();

            var shipment = await db.Shipments.FindAsync(id);
            if (shipment is null) return Results.NotFound();

            shipment.Status = request.Status;
            shipment.EstimatedDelivery = request.EstimatedDelivery;
            shipment.Notes = request.Notes;

            if (request.Status == ShipmentStatus.Delivered && shipment.ActualDelivery is null)
                shipment.ActualDelivery = DateTime.UtcNow;

            await db.SaveChangesAsync();
            return Results.Ok(shipment.ToDto());
        });

        // DELETE shipment (dispatchers only)
        group.MapDelete("/{id:int}", async (int id, ApplicationDbContext db, ClaimsPrincipal user) =>
        {
            var role = await GetUserRole(db, user);
            if (role != "Dispatcher") return Results.Forbid();

            var shipment = await db.Shipments.FindAsync(id);
            if (shipment is null) return Results.NotFound();

            db.Shipments.Remove(shipment);
            await db.SaveChangesAsync();
            return Results.NoContent();
        });
    }

    private static async Task<string> GetUserRole(ApplicationDbContext db, ClaimsPrincipal user)
    {
        var userId = user.FindFirstValue(ClaimTypes.NameIdentifier);
        if (userId is null) return "Customer";

        var appUser = await db.Users.FindAsync(userId);
        return appUser?.Role ?? "Customer";
    }

    private static string GenerateTrackingNumber()
    {
        return $"SHP-{DateTime.UtcNow:yyyyMMdd}-{Random.Shared.Next(10000, 99999)}";
    }
}

