@code {
    private List<ShipmentDto>? shipments;
    private string searchTerm = "";
    private string statusFilter = "";
    private string sortColumn = "ShippedDate";
    private bool sortAscending = false;
    private string userRole = "Customer";
    private bool showCreateForm = false;
    private bool isSubmitting = false;
    private CreateShipmentRequest newShipment = new();

    // Edit state
    private ShipmentDto? editingShipment;
    private ShipmentStatus editStatus;
    private DateTime editEstimatedDelivery;
    private string? editNotes;

    private IEnumerable<ShipmentDto> FilteredShipments
    {
        get
        {
            if (shipments is null) return Enumerable.Empty<ShipmentDto>();

            var filtered = shipments.AsEnumerable();

            if (!string.IsNullOrWhiteSpace(searchTerm))
            {
                var term = searchTerm.ToLowerInvariant();
                filtered = filtered.Where(s =>
                    s.TrackingNumber.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                    s.Destination.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                    s.RecipientName.Contains(term, StringComparison.OrdinalIgnoreCase));
            }

            if (!string.IsNullOrWhiteSpace(statusFilter) && Enum.TryParse<ShipmentStatus>(statusFilter, out var status))
                filtered = filtered.Where(s => s.Status == status);

            filtered = sortColumn switch
            {
                "TrackingNumber" => sortAscending ? filtered.OrderBy(s => s.TrackingNumber) : filtered.OrderByDescending(s => s.TrackingNumber),
                "Destination" => sortAscending ? filtered.OrderBy(s => s.Destination) : filtered.OrderByDescending(s => s.Destination),
                "Status" => sortAscending ? filtered.OrderBy(s => s.Status) : filtered.OrderByDescending(s => s.Status),
                "EstimatedDelivery" => sortAscending ? filtered.OrderBy(s => s.EstimatedDelivery) : filtered.OrderByDescending(s => s.EstimatedDelivery),
                _ => filtered
            };

            return filtered;
        }
    }

    protected override async Task OnInitializedAsync()
    {
        try
        {
            var roleResponse = await Http.GetFromJsonAsync<RoleResponse>("/api/user/role");
            userRole = roleResponse?.Role ?? "Customer";
        }
        catch { }

        await LoadShipments();
    }

    private async Task LoadShipments()
    {
        try
        {
            shipments = await Http.GetFromJsonAsync<List<ShipmentDto>>("/api/shipments");
        }
        catch
        {
            shipments = new();
        }
    }

    private void SortBy(string column)
    {
        if (sortColumn == column)
            sortAscending = !sortAscending;
        else
        {
            sortColumn = column;
            sortAscending = true;
        }
    }

    private string SortIndicator(string column) =>
        sortColumn == column ? (sortAscending ? "▲" : "▼") : "";

    private async Task CreateShipment()
    {
        isSubmitting = true;
        try
        {
            var response = await Http.PostAsJsonAsync("/api/shipments", newShipment);
            if (response.IsSuccessStatusCode)
            {
                newShipment = new();
                showCreateForm = false;
                await LoadShipments();
            }
        }
        finally { isSubmitting = false; }
    }

    private void StartEdit(ShipmentDto shipment)
    {
        editingShipment = shipment;
        editStatus = shipment.Status;
        editEstimatedDelivery = shipment.EstimatedDelivery;
        editNotes = shipment.Notes;
    }

    private void CancelEdit() => editingShipment = null;

    private async Task SaveEdit()
    {
        if (editingShipment is null) return;
        isSubmitting = true;
        try
        {
            var update = new UpdateShipmentRequest
            {
                Status = editStatus,
                EstimatedDelivery = editEstimatedDelivery,
                Notes = editNotes
            };
            var response = await Http.PutAsJsonAsync($"/api/shipments/{editingShipment.Id}", update);
            if (response.IsSuccessStatusCode)
            {
                editingShipment = null;
                await LoadShipments();
            }
        }
        finally { isSubmitting = false; }
    }

    private async Task DeleteShipment(int id)
    {
        var response = await Http.DeleteAsync($"/api/shipments/{id}");
        if (response.IsSuccessStatusCode)
            await LoadShipments();
    }

    private static string StatusBadgeClass(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Pending => "bg-secondary",
        ShipmentStatus.PickedUp => "bg-info",
        ShipmentStatus.InTransit => "bg-primary",
        ShipmentStatus.OutForDelivery => "bg-warning text-dark",
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.Delayed => "bg-danger",
        ShipmentStatus.Returned => "bg-dark",
        _ => "bg-secondary"
    };

    private record RoleResponse(string Role);
}

